-- S1.1: tipo do requerimento, objeto, prioridade, responsável da tarefa e número de processo repetido.
-- Dados fictícios (nenhum dado real).

UPDATE SIGA2_LICENCIAMENTO.REQUERIMENTO SET ID_TIPO_REQUERIMENTO = 1 WHERE ID = 101;

-- 101 é de outorga: 4 ligações de objetivo (1 vencida, 1 futura) e 2 pares finalidade/atividade
-- (o segundo com atividade inexistente em ATIVIDADE).


-- 102 é de licenciamento com 2 objetivos; 103 é de licenciamento sem objetivos; 104 e 105 não têm nenhum bloco.

-- Prioridade: 101 com 2 critérios (5 e 2); 102 tem o cabeçalho mas nenhum critério; 103 não tem nada.

-- Responsável pela tarefa (requerimentos 301 a 306). CPFs fictícios.
--   301: SERVIDOR com 2 versões (vale a mais recente) e PESSOA com outro nome (SERVIDOR tem preferência)
--   302: só em PESSOA            303: em nenhuma tabela      304: ASSIGNEE_ nulo
--   305: 'demo' (outro formato)  306: SERVIDOR e PESSOA
SELECT 300 + LEVEL, TO_CHAR(300 + LEVEL) || '/2026', NULL, TIMESTAMP '2026-03-01 00:00:00', NULL, 'EM_ANALISE', NULL, 1
FROM   DUAL
CONNECT BY LEVEL <= 6;
SELECT 'p' || TO_CHAR(300 + LEVEL), 'p' || TO_CHAR(300 + LEVEL), NULL, TO_CHAR(300 + LEVEL)
FROM   DUAL
CONNECT BY LEVEL <= 6;

